//! Test tolerances (DESIGN.md §9.2), read from `tests/tolerances.toml`.
//!
//! Every correctness test takes its thresholds from that one file, so loosening a gate is a reviewed
//! one-line change. The file is generated by `reference/noise_stats.py --write-tolerances` from measured noise
//! and uses a small TOML subset: `[a.b]` tables, `key = number | "string" | true | false`, and `#` comments.
//! Keys are addressed by their dotted path, e.g. `e2e.bf16.dp_p99`.
//!
//! [`Stats`] is the distribution summary every test prints (p50/p99/max, nearest rank, as the Python side).

use std::collections::BTreeMap;
use std::path::Path;

use anyhow::{Context, Result, bail};

#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Num(f64),
    Str(String),
    Bool(bool),
}

#[derive(Clone, Debug, Default)]
pub struct Tolerances {
    values: BTreeMap<String, Value>,
}

/// Path of the repository's tolerance file.
pub fn default_path() -> &'static str {
    concat!(env!("CARGO_MANIFEST_DIR"), "/tests/tolerances.toml")
}

impl Tolerances {
    pub fn load(path: impl AsRef<Path>) -> Result<Self> {
        let path = path.as_ref();
        let text = std::fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
        Self::parse(&text).with_context(|| format!("parsing {}", path.display()))
    }

    pub fn load_default() -> Result<Self> {
        Self::load(default_path())
    }

    pub fn parse(text: &str) -> Result<Self> {
        let mut values = BTreeMap::new();
        let mut table = String::new();
        for (n, raw) in text.lines().enumerate() {
            let line = strip_comment(raw).trim();
            if line.is_empty() {
                continue;
            }
            if let Some(rest) = line.strip_prefix('[') {
                let Some(name) = rest.strip_suffix(']') else { bail!("line {}: unterminated table header", n + 1) };
                let name = name.trim();
                if name.is_empty() || !name.split('.').all(is_bare_key) {
                    bail!("line {}: bad table name {name:?}", n + 1);
                }
                table = name.to_string();
                continue;
            }
            let Some((key, val)) = line.split_once('=') else { bail!("line {}: expected key = value", n + 1) };
            let key = key.trim();
            if !is_bare_key(key) {
                bail!("line {}: bad key {key:?}", n + 1);
            }
            let val = parse_value(val.trim()).with_context(|| format!("line {}", n + 1))?;
            let full = if table.is_empty() { key.to_string() } else { format!("{table}.{key}") };
            if values.insert(full.clone(), val).is_some() {
                bail!("line {}: duplicate key {full}", n + 1);
            }
        }
        Ok(Self { values })
    }

    pub fn get(&self, key: &str) -> Option<&Value> {
        self.values.get(key)
    }

    pub fn f64(&self, key: &str) -> Result<f64> {
        match self.values.get(key) {
            Some(Value::Num(x)) => Ok(*x),
            Some(v) => bail!("tolerance {key} is {v:?}, not a number"),
            None => bail!("tolerance {key} is missing from {}", default_path()),
        }
    }

    pub fn str(&self, key: &str) -> Result<&str> {
        match self.values.get(key) {
            Some(Value::Str(s)) => Ok(s),
            Some(v) => bail!("tolerance {key} is {v:?}, not a string"),
            None => bail!("tolerance {key} is missing"),
        }
    }

    /// All keys under `prefix.` (dotted), in order.
    pub fn keys_under<'a>(&'a self, prefix: &'a str) -> impl Iterator<Item = &'a str> + 'a {
        self.values.keys().map(String::as_str).filter(move |k| k.len() > prefix.len() + 1
            && k.starts_with(prefix)
            && k.as_bytes()[prefix.len()] == b'.')
    }

    pub fn keys(&self) -> impl Iterator<Item = &str> {
        self.values.keys().map(String::as_str)
    }
}

fn is_bare_key(k: &str) -> bool {
    !k.is_empty() && k.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

/// Drop a trailing `# comment`, ignoring `#` inside a double-quoted string.
fn strip_comment(line: &str) -> &str {
    let mut in_str = false;
    for (i, c) in line.char_indices() {
        match c {
            '"' => in_str = !in_str,
            '#' if !in_str => return &line[..i],
            _ => {}
        }
    }
    line
}

fn parse_value(v: &str) -> Result<Value> {
    if let Some(s) = v.strip_prefix('"') {
        let Some(s) = s.strip_suffix('"') else { bail!("unterminated string {v:?}") };
        if s.contains('"') || s.contains('\\') {
            bail!("escapes are not supported in {v:?}");
        }
        return Ok(Value::Str(s.to_string()));
    }
    match v {
        "true" => return Ok(Value::Bool(true)),
        "false" => return Ok(Value::Bool(false)),
        _ => {}
    }
    let x: f64 = v.replace('_', "").parse().with_context(|| format!("bad value {v:?}"))?;
    if !x.is_finite() {
        bail!("non-finite value {v:?}");
    }
    Ok(Value::Num(x))
}

/// Distribution summary of an error sample (nearest-rank quantiles).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Stats {
    pub n: usize,
    pub p50: f64,
    pub p99: f64,
    pub max: f64,
}

impl Stats {
    pub fn of(xs: &[f64]) -> Option<Stats> {
        if xs.is_empty() {
            return None;
        }
        let mut s = xs.to_vec();
        s.sort_by(f64::total_cmp);
        let q = |p: f64| s[((p * s.len() as f64).ceil() as usize).clamp(1, s.len()) - 1];
        Some(Stats { n: s.len(), p50: q(0.50), p99: q(0.99), max: s[s.len() - 1] })
    }
}

impl std::fmt::Display for Stats {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "n={} p50={:.3e} p99={:.3e} max={:.3e}", self.n, self.p50, self.p99, self.max)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = r#"
# top comment
schema = 1
note = "a # inside a string"   # trailing
[e2e.bf16]
dp_p99 = 0.015
measured_dp_p99 = 1e-2  # bf16_fork: dp_option p99
strict = true
"#;

    #[test]
    fn parses_the_subset() {
        let t = Tolerances::parse(SAMPLE).unwrap();
        assert_eq!(t.f64("schema").unwrap(), 1.0);
        assert_eq!(t.str("note").unwrap(), "a # inside a string");
        assert_eq!(t.f64("e2e.bf16.dp_p99").unwrap(), 0.015);
        assert_eq!(t.f64("e2e.bf16.measured_dp_p99").unwrap(), 0.01);
        assert_eq!(t.get("e2e.bf16.strict"), Some(&Value::Bool(true)));
        assert_eq!(t.keys_under("e2e.bf16").count(), 3);
        assert!(t.f64("e2e.bf16.missing").is_err());
        assert!(t.f64("note").is_err());
    }

    #[test]
    fn rejects_malformed_input() {
        for bad in ["[e2e", "x", "x = ", "x = \"open", "x = nan", "[a]\nk = 1\nk = 2", "[a b]", "bad key = 1"] {
            assert!(Tolerances::parse(bad).is_err(), "accepted {bad:?}");
        }
    }

    #[test]
    fn stats_use_nearest_rank() {
        let xs: Vec<f64> = (1..=200).map(f64::from).collect();
        let s = Stats::of(&xs).unwrap();
        assert_eq!((s.n, s.p50, s.p99, s.max), (200, 100.0, 198.0, 200.0));
        assert_eq!(Stats::of(&[3.0]).unwrap().p99, 3.0);
        assert!(Stats::of(&[]).is_none());
    }

    /// The committed file parses, and no threshold sits below the reference noise it derives from: a gate
    /// tighter than the reference's own spread could never pass.
    #[test]
    fn repository_tolerances_are_consistent() {
        let t = Tolerances::load_default().unwrap();
        assert_eq!(t.f64("schema").unwrap(), 1.0);
        let factor = t.f64("factor").unwrap();
        assert!(factor >= 1.0);
        let mut checked = 0;
        for key in t.keys() {
            let Some((table, name)) = key.rsplit_once('.') else { continue };
            let Some(base) = name.strip_prefix("measured_") else { continue };
            let threshold = format!("{table}.{base}");
            let Ok(limit) = t.f64(&threshold) else { continue };
            let measured = t.f64(key).unwrap();
            assert!(measured >= 0.0, "{key} = {measured}");
            assert!(limit >= measured, "{threshold} = {limit} is below its measured envelope {measured}");
            checked += 1;
        }
        for gate in ["e2e.bf16.dp_p99", "e2e.bf16.dp_max", "e2e.fp32_truth.dp_max", "batch_invariance.dp_max",
                     "nvfp4.dp_p99", "nvfp4.dp_max"] {
            assert!(t.f64(gate).is_ok(), "missing {gate}");
        }
        assert!(checked >= 10, "only {checked} thresholds carry a measurement");
    }
}
